package org.eclipse.kura.internal.rest.auth.jwt;

import org.junit.Test;

import jakarta.ws.rs.core.Response.Status;

public class RefreshTokenFamilyIdentityRemovalTest extends AbstractRefreshTokenFamilyScenario {

    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();

    private String refreshToken;

    @Test
    public void reCreatingAnIdentityWithoutPasswordDoesNotReviveTheFamily() {
        givenTheOwnerLoggedIn();
        givenTheIdentityIsRemoved();
        givenTheRefreshTokenWasExchanged(this.refreshToken);
        givenTheIdentityIsCreated();

        whenTheRefreshTokenIsExchanged(this.refreshToken);

        thenTheExchangeStatusesAre(UNAUTHORIZED, UNAUTHORIZED);
    }

    private void givenTheOwnerLoggedIn() {
        this.refreshToken = login().refreshToken();
    }

    private void givenTheIdentityIsRemoved() {
        removeIdentity(IDENTITY);
    }

    private void givenTheIdentityIsCreated() {
        createIdentity(IDENTITY);
    }

    private void givenTheRefreshTokenWasExchanged(final String token) {
        exchange(token);
    }

    private void whenTheRefreshTokenIsExchanged(final String token) {
        exchange(token);
    }
}
